import { ChangeDetectionStrategy, Component } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { FancyPillComponent } from "../../lib/fancy-pill.component";
import { HintDirective } from "../../lib/hint.directive";
import { PillComponent, type PillVariant } from "../../lib/pill.component";
import { StatusPillComponent } from "../../lib/status-pill.component";

@Component({
    selector: "app-feature-25",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, FancyPillComponent, StatusPillComponent, CardComponent, HintDirective ],
    template: `
        <app-card heading="Feature 25" [disableTooltip]="true">
            <p class="hint">This card sets disableTooltip: its title shows no hint.</p>
            <app-pill label="Plain" hideHint />
            <app-pill variant="success" label="Active" [hideHint]="!isActive" />
            <app-pill [label]="count > 3 ? 'Many' : title" [hideHint]="count > 3" />
            <app-pill
                [variant]="isActive ? 'success' : 'warning'"
                label="Multi-line"
                [hideHint]="isActive">
            </app-pill>
            @if (isActive) {
                <app-pill [variant]="statusVariant" label="Nested" [hideHint]="false" />
            }
            <app-fancy-pill
                [icon]="count > 2 ? 'bolt' : 'star'"
                [disableTooltip]="count > 5"
                label="Fancy" />
            <app-status-pill label="Status" [variant]="statusVariant" [hideHint]="count === 0" />
            <small appHint="More about feature 25" [hintDisabled]="!isActive">More</small>
        </app-card>
        <app-card heading="Summary" [disableTooltip]="!isActive" />
    `
})
export class Feature025Component {
    isActive = false;
    count = 4;
    title = "Title 25";
    statusVariant: PillVariant = "success";
}

